SELECT COUNT(*) FROM biz_booking
WHERE employee_id = #{employeeId}
  AND store_id = #{storeId}
  AND status IN (1, 2, 3)
  AND deleted = 0
  AND start_time < #{endTime}
  AND end_time > #{startTime}
FOR UPDATE

